// EXCURSIA_HARDBLOCK_20260906_V1
(() => {
  'use strict';
  const blocked = /(?:excursia(?:\.cz)?|2e6a0944|76c9b39c|1ef717c8|27bb200a|2ae526f8|368140a3|3ad1c473|42c81f52|5950833c|6312aab5|80cbf20d|993000bf|b39d7f2a|c9a10c7f|cc734358|dac71170|e3c0d4ee|f92543ca)/i;
  const selector = [
    'a.promo-card',
    'a.article-rail-card',
    '.featured-rotating-ad a',
    '.featured-seasonal-ad a',
    '.article-aside-adstream a',
    '[data-promos] a',
    '.promo-wrap a',
    '.article-ad-auto a',
    '.article-ad-rail a',
    '.nk-home-lms a',
    'img[src*="2e6a0944"]',
    'img[src*="excursia"]'
  ].join(',');

  const signature = (node) => {
    if (!(node instanceof Element)) return '';
    const href = node.getAttribute('href') || '';
    const src = node.getAttribute('src') || '';
    return `${href} ${src} ${node.textContent || ''} ${node.innerHTML || ''}`;
  };

  const removeBlocked = (node) => {
    if (!(node instanceof Element) || !blocked.test(signature(node))) return;
    const card =
      node.closest('a.promo-card,a.article-rail-card') ||
      node.closest('.featured-rotating-ad,.featured-seasonal-ad') ||
      node.closest('.article-ad-auto,.article-ad-rail') ||
      node.closest('a') ||
      node;
    card.remove();
  };

  const purge = (root = document) => {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    root.querySelectorAll(selector).forEach(removeBlocked);
  };

  const start = () => {
    purge();
    if (!document.documentElement) return;
    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        for (const added of mutation.addedNodes) {
          if (!(added instanceof Element)) continue;
          if (added.matches && added.matches(selector)) removeBlocked(added);
          purge(added);
        }
      }
    });
    observer.observe(document.documentElement, {childList: true, subtree: true});
    [250, 800, 1800, 3500, 7000].forEach((delay) => setTimeout(purge, delay));
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, {once: true});
  } else {
    start();
  }

  document.addEventListener('click', (event) => {
    const anchor = event.target instanceof Element ? event.target.closest('a') : null;
    if (!anchor || !blocked.test(signature(anchor))) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    removeBlocked(anchor);
  }, true);
})();

